def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=3 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and grid[yy][xx]==3 and (yy,xx) not in seen:
              seen.add((yy,xx)); stack.append((yy,xx))
        r0=min(y for y,x in comp); r1=max(y for y,x in comp)
        c0=min(x for y,x in comp); c1=max(x for y,x in comp)
        for y in range(r0,r1+1):
          for x in range(c0,c1+1):
            if grid[y][x]==2:
              for dy in (-1,0,1):
                for dx in (-1,0,1):
                  yy,xx=y+dy,x+dx
                  if 0<=yy<h and 0<=xx<w and grid[yy][xx]==3: out[yy][xx]=1
    return out
